"""Explain idle, killable and high-resolution wait contracts."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1481': ('쉬는 사람을 “일이 밀려 기다리는 사람” 수에 넣지 않는 표시를 생각해 봅시다. 표시를 붙였다고 그 사람이 계속 뛰어다니거나 건물 전체가 쉬는 것은 아닙니다.', 'TASK_IDLE의 부하 집계와 실제 대기 동작을 구별합니다.', 'TASK_IDLE = UNINTERRUPTIBLE | NOLOAD를 적으세요. 조건 거짓 → schedule → 조건 재확인을 그리세요.', ['시스템 load는 실행 중이거나 특정 기다림에 있는 작업 등을 반영하는 부하 지표입니다. CPU 사용률과 완전히 같은 숫자는 아닙니다. TASK_IDLE은 이 대기 때문에 시스템 load를 늘리지 않도록 하는 상태 조합입니다.', '정의는 TASK_UNINTERRUPTIBLE과 TASK_NOLOAD를 OR로 합친 값입니다. NOLOAD가 부하 집계와 관련된 표시이고, UNINTERRUPTIBLE은 일반 신호 중단을 허용하는 TASK_INTERRUPTIBLE과 다른 대기 규칙입니다.', 'wait_event_idle는 처음 조건을 확인하고 거짓이면 공통 대기로 들어갑니다. 대기 명령은 schedule입니다. 조건이 바뀔 때까지 CPU에서 계속 확인만 반복하는 바쁜 반복문을 만드는 것이 아닙니다.', '또한 idle이라는 이름이 시스템의 CPU idle 태스크로 현재 작업을 바꾸거나 모든 CPU를 절전 상태로 만든다는 뜻은 아닙니다. 이 호출에서 기다리는 현재 태스크의 상태와 집계 방식을 선택합니다.', 'idle_exclusive는 같은 상태에 exclusive 등록을 더합니다. idle_timeout 계열은 jiffies 단위 시간 제한을 더해 조건 미충족 만료는 0, 조건 성공은 양수로 알립니다. 만료 경계에서 조건이 참이면 성공 표시 1이 됩니다.', '따라서 대기 상태, 깨우기 한도 표시, 반환값을 각각 읽으세요. idle이라는 이름만으로 신호 중단이 가능하다고 추측하지 않습니다. 조건 변경 뒤 깨우기와 공유 자료 보호 규약도 여전히 필요합니다.'], [('wait_event_idle가 실제 대기를 위해 사용하는 명령은?', ['CPU를 계속 쓰는 바쁜 반복문뿐이에요', '공통 반복문의 schedule이에요'], '공통 매크로의 명령 인자는 schedule입니다. load에 기여하지 않는 상태라는 설명을 계속 실행하면서 확인한다는 뜻으로 읽으면 안 됩니다.'), ('idle_timeout이 0을 반환했다면?', ['조건을 만족하지 못한 채 시간이 끝난 것이에요', '반드시 조건 성공을 뜻해요'], '이 시간 제한 변형은 일반 jiffies timeout 도우미를 사용합니다. 성공은 양수이고 조건 미충족 만료가 0이므로 TASK_IDLE 상태 이름으로 반환 계약을 바꾸어 읽지 마세요.')]), 'os1482': ('“긴급 중단 연락을 받으면 나간다”는 규칙과 “지금 연락이 와 있다”는 사실은 다릅니다. 어떤 연락을 확인해야 하는지와 실제 연락 유무를 따로 봐야 합니다.', 'killable 상태와 신호 검사 필요 여부를 실제 신호 도착과 구별합니다.', '검사 필요? → 실제 허용 신호 있음? → 조건 재확인 → 오류 또는 성공으로 흐름을 적으세요. 첫 질문의 참만으로 오류라고 적지 마세요.', ['wait_event_killable은 TASK_KILLABLE 상태로 대기합니다. 이 상태는 TASK_UNINTERRUPTIBLE과 TASK_WAKEKILL을 합친 값입니다. 일반적인 모든 신호에 반응하는 interruptible과 달리 치명적인 종료 신호에 반응할 수 있게 하는 규칙입니다.', '시간 제한 없는 killable의 조건 성공은 0, 허용 신호로 중단되면 -ERESTARTSYS입니다. killable_timeout은 남은 jiffies의 양수 성공, 0 만료, 음수 신호 오류라는 시간 제한 규칙을 결합합니다.', 'wait_event_state는 호출자가 state를 직접 전달합니다. 항상 TASK_INTERRUPTIBLE로 바꾸지 않습니다. 선택한 상태가 어떤 깨우기와 신호를 허용하는지 호출자가 확인해야 하며 아무 숫자나 넣어도 되는 것은 아닙니다.', '___wait_is_interruptible은 컴파일할 때 state를 상수로 알 수 있는지 살핍니다. 상수로 알 수 있으면 INTERRUPTIBLE 또는 WAKEKILL 비트를 확인합니다. 컴파일 시간은 실행 전 코드를 기계가 실행할 형태로 번역하는 때입니다.', '상수로 판단할 수 없다면 오류 검사를 남겨 두기 위해 이 매크로는 참이 됩니다. 이것은 실제로 신호가 왔다는 뜻이 아닙니다. signal_pending_state가 실제 신호와 대기 상태를 검사하는 별도 단계입니다.', '공통 매크로는 조건부터 보고, 거짓일 때 검사 필요 여부와 준비 함수의 실제 오류를 함께 봅니다. 따라서 검사 필요=true, 실제 오류=0이면 그 이유만으로 중단하지 않습니다. 신호 정책, 실제 도착, 조건 성공을 세 가지 질문으로 나눠 읽으세요.'], [('___wait_is_interruptible이 참이면 실제 신호가 도착한 증거일까요?', ['네. 신호 목록이 비어 있지 않다는 증거예요', '아니요. 오류 검사를 할 필요가 있다는 판정이에요'], '이 매크로는 state의 상수 여부와 비트를 봅니다. 실제 신호 확인은 준비 함수의 별도 검사이므로 참 하나만으로 신호 도착을 결론 내리면 안 됩니다.'), ('wait_event_state는 어떤 대기 상태를 사용할까요?', ['호출자가 인자로 준 state를 사용해요', '항상 TASK_INTERRUPTIBLE로 강제해요'], '내부 매크로에 전달받은 state를 그대로 넘깁니다. 따라서 호출자가 그 상태의 대기·신호 계약을 확인해야 하며 항상 interruptible이라는 답은 틀립니다.')]), 'os1483': ('기다릴 때 작은 알람을 준비하고, 시간이 끝나면 알람 담당자가 표시를 바꿉니다. 기다림이 먼저 끝나더라도 알람을 정리해야 나중에 없어진 물건을 건드리지 않습니다.', '고해상도 타이머의 준비·만료 표시·취소 흐름을 배웁니다.', '타이머 초기화 → 유한 시간이면 시작 → 조건·신호 검사 → 만료 표시 검사 → 필요하면 대기 → 타이머 취소·정리를 그리세요.', ['__wait_event_hrtimeout은 스택에 hrtimer_sleeper라는 타이머 자료를 준비합니다. hrtimer는 더 세밀한 시간 표현을 사용하는 고해상도 타이머입니다. 스택 자료는 이 코드 실행 범위가 끝나면 계속 써서는 안 되는 임시 자료입니다.', 'CLOCK_MONOTONIC과 HRTIMER_MODE_REL로 초기화합니다. 전자는 경과 시간에 사용하는 시계 종류이고 후자는 현재 기준으로 얼마 뒤라는 상대 모드입니다. 시간 인자는 ktime_t이며 앞서 본 jiffies 개수와 같은 계약이 아닙니다.', '시간이 KTIME_MAX가 아니면 만료 시간과 current->timer_slack_ns를 설정하고 시작합니다. slack은 타이머 만료에 허용하는 여유 범위입니다. 세밀한 타이머라고 태스크가 정확히 지정 순간에 CPU를 얻는다고 보장하는 것은 아닙니다.', 'KTIME_MAX이면 이 내부 함수는 만료 설정과 시작을 건너뜁니다. 하지만 초기화는 그 분기보다 앞에 있습니다. 내부 함수가 실행된 경우 공통 종료의 취소와 스택 타이머 정리도 남아 있으므로 객체를 전혀 만들지 않는 길은 아닙니다.', '타이머의 깨우기 함수는 sleeper의 task를 NULL로 바꾸고 대상이 있으면 깨웁니다. 대기 명령은 !__t.task를 만료 표시로 보아 -ETIME을 설정하고 반복을 끝냅니다. 공통 조건 검사가 이 명령보다 먼저라 조건이 맞으면 성공 길로 나갈 수 있습니다.', '대기가 끝나면 hrtimer_cancel과 destroy_hrtimer_on_stack을 실행합니다. 예약된 타이머 접근을 정리하고 임시 타이머 사용을 마무리하는 순서입니다. 반환값은 남은 jiffies가 아니라 성공·오류 코드이며, 타이머 객체와 실제 기다리던 자원의 수명도 구별해야 합니다.'], [('고해상도 대기에서 조건을 못 맞추고 시간 만료로 끝나면 코드는?', ['항상 jiffies timeout처럼 0이에요', '-ETIME이에요'], '내부 만료 검사는 __ret=-ETIME을 설정합니다. 이 API의 성공은 0이므로 일반 jiffies 대기의 0 만료 규칙을 그대로 적용하면 안 됩니다.'), ('내부 함수에 KTIME_MAX를 주면 타이머 초기화도 생략할까요?', ['아니요. 만료 설정과 시작만 건너뛰어요', '네. 초기화와 정리를 모두 생략해요'], '초기화는 if보다 앞에 있고 취소와 정리는 공통 종료 부분입니다. 분기 안의 명령만 생략되는 범위를 정확히 읽어야 합니다.')]), 'os1484': ('같은 숫자 0도 게임에 따라 성공 표시일 수도, 시간 초과 표시일 수도 있습니다. 함수마다 정한 규칙표를 먼저 보고 결과를 해석해야 합니다.', '고해상도 대기 wrapper의 0 성공과 신호 상태 차이를 이해합니다.', 'hrtimeout: 0 성공·-ETIME 만료. interruptible_hrtimeout: 위 두 값과 -ERESTARTSYS 신호 중단을 적으세요.', ['wait_event_hrtimeout은 일반 고해상도 대기입니다. 조건이 참이 되어 끝나면 0, 시간 만료로 끝나면 -ETIME을 반환합니다. 결과에 남은 jiffies를 담는 앞선 wait_event_timeout과 다릅니다.', '이 wrapper가 내부에 주는 상태는 TASK_UNINTERRUPTIBLE입니다. 문서에 넓게 신호를 언급한 문장이 있어도 실제 상태 인자와 오류 경로를 함께 봐야 합니다. 일반 신호로 중단 가능한 상태를 선택한 것은 아닙니다.', 'wait_event_interruptible_hrtimeout은 TASK_INTERRUPTIBLE을 전달합니다. 그래서 조건 성공 0과 만료 -ETIME 외에, 허용된 신호로 중단될 때 -ERESTARTSYS도 나올 수 있습니다. 이름의 interruptible이 실제 인자 차이로 이어집니다.', '두 바깥 wrapper는 먼저 결과를 0으로 준비하고 조건을 확인합니다. 이미 참이면 내부 타이머 함수를 부르지 않고 0으로 끝납니다. 이 경우에는 스택 타이머 초기화도 생략됩니다. 내부 함수의 KTIME_MAX 분기와는 다른 생략 지점입니다.', '실제 내부 반복은 준비 뒤 조건 성공을 먼저 검사하고 다음에 허용된 신호 오류, 그 뒤 대기 명령의 만료 표시를 봅니다. 예를 들어 조건이 거짓이고 허용 신호와 만료를 함께 관측하면 신호 오류가 먼저 나갈 수 있습니다. 검사 위치를 따라 판단하세요.', '따라서 결과 판정은 이 API의 약속에 맞춰 0 성공, -ETIME 만료, 해당 변형의 -ERESTARTSYS 중단을 구별합니다. 고해상도라는 이름만으로 정확한 깨움 시각이나 모든 환경의 동일한 지연을 주장하지 않습니다. 실제 타이머와 스케줄러 동작은 별도로 확인할 대상입니다.'], [('hrtimeout이 조건 성공으로 반환한 0은 실패일까요?', ['네. 모든 timeout API의 0은 실패예요', '아니요. 이 API에서는 0이 조건 성공이에요'], 'hrtimeout은 성공 0, 만료 -ETIME을 사용합니다. jiffies 대기의 0 만료·양수 성공과 다른 약속이므로 이름만 보고 통일해 외우면 틀립니다.'), ('일반 wait_event_hrtimeout이 전달하는 상태는?', ['TASK_UNINTERRUPTIBLE이에요', '항상 TASK_INTERRUPTIBLE이에요'], '실제 내부 호출 인자는 TASK_UNINTERRUPTIBLE입니다. 신호 중단이 필요한 별도 interruptible 변형과 구별해야 합니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_366.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
